WoWFA_En[475] = "Removes all Curses from a friendly target. $?s115700[If any Curses are successfully removed, you deal $115701s1% additional damage for $115701d.][]"
WoWFA_Data[475] = "تمام Curses را از یک هدف دوستانه حذف می‌کند. $?s115700[اگر Curses با موفقیت حذف شوند، برای $115701d، $115701s1% آسیب اضافی وارد می‌کنید.][]"
WoWFA_En[2120] = "Calls down a pillar of fire, burning all enemies within the area for $s1 Fire damage. Deals reduced damage beyond $s2 targets.$?a205037[\n\nLeaves behind a patch of flames that burns enemies within it for ${$205470d*$205472s1} Fire damage over $205470d.][]\n\n|cFFFFFFFFThis spell is cast at a selected location.|r"
WoWFA_Data[2120] = "ستونی از آتش فرومی‌فرستد و همهٔ دشمنان در ناحیه را به‌اندازهٔ $s1 آسیب Fire می‌سوزاند. آسیب پس از 8 هدف کاهش می‌یابد.$?a205037[\n\nلکه‌ای از شعله‌ها بر جای می‌گذارد که دشمنان داخل آن را طی 6 ثانیه به‌اندازهٔ ${$205470d*$205472s1} آسیب Fire می‌سوزاند.][]\n\n|cFFFFFFFFاین اسپل در مکان انتخاب‌شده کست می‌شود.|r"
WoWFA_En[2948] = "Scorches an enemy for $s1 Fire damage.\n\nWhen cast on a target below $s2% health, Scorch is a guaranteed critical strike.\n\nCastable while moving."
WoWFA_Data[2948] = "دشمنی را به‌اندازهٔ $s1 آسیب Fire می‌سوزاند.\n\nوقتی روی هدفی با سلامتی کمتر از 30% کست شود، Scorch حتماً Critical Strike می‌زند.\n\nهنگام حرکت نیز قابل کست است."
WoWFA_En[5143] = "|cFFFFFFFFRequires Clearcasting|r\nLaunches ${($d/$t1)+1} waves of Arcane Missiles at the enemy over $5143d, causing a total of ${($d/$t1)*$7268s1} Arcane damage."
WoWFA_Data[5143] = "|cFFFFFFFFبه Clearcasting نیاز دارد|r\nطی 2.5 ثانیه، 5 موج Arcane Missiles به‌سوی دشمن پرتاب می‌کنید که در مجموع ${($d/$t1)*$7268s1} آسیب Arcane وارد می‌کند."
WoWFA_En[11366] = "Hurls an immense fiery boulder that causes $s1 Fire damage$?a321711[ and an additional $321712o2 Fire damage over $321712d][]."
WoWFA_Data[11366] = "تخته‌سنگ آتشین بزرگی پرتاب می‌کند که $s1 آسیب Fire وارد می‌کند$?a321711[ و طی 6 ثانیه، $321712o2 آسیب Fire اضافی وارد می‌کند][]."
WoWFA_En[11426] = "Shields you with ice, absorbing $<shield> damage$?s235297[ and increasing your armor by $s3%][] for $d.\n\nMelee attacks against you reduce the attacker's movement speed by $205708s1%."
WoWFA_Data[11426] = "شما را با یخ محافظت می‌کند و برای 1 دقیقه، $<shield> آسیب را جذب می‌کند$?s235297[ و Armor شما را $s3% افزایش می‌دهد][].\n\nحملات نزدیک علیه شما سرعت حرکت مهاجم را به‌اندازهٔ 50% کاهش می‌دهند."
WoWFA_Data[12051] = "بازسازی Mana شما را به‌اندازه 1500% برای 3 ثانیه افزایش می‌دهد."
WoWFA_En[30449] = "Steals $?s198100[all beneficial magic effects from the target. These effects lasts a maximum of 2 min][a beneficial magic effect from the target. This effect lasts a maximum of 2 min]."
WoWFA_Data[30449] = "$?s198100[تمام اثرات Magic سودمند را از هدف می‌رباید. این اثرات حداکثر 2 دقیقه دوام دارند][یک اثر Magic سودمند را از هدف می‌رباید. این اثر حداکثر 2 دقیقه دوام دارد]."
WoWFA_En[30455] = "Quickly fling a shard of ice at the target, dealing $228598s1 Frost damage.\n\n|CFFffffffShatters $1246769s4 stacks of Freezing.|R"
WoWFA_Data[30455] = "تکه‌ای از یخ را با سرعت به سمت هدف پرتاب می‌کنید و $228598s1 آسیب Frost وارد می‌کنید.\n\n|CFFffffff4 استک Freezing را Shatter می‌کند.|R"
WoWFA_En[31661] = "Enemies in a $s3 yd cone in front of you take $s2 Fire damage and are disoriented for $d. Damage will cancel the effect.$?a235870[\n\nAlways deals a critical strike and contributes to Hot Streak.][]"
WoWFA_Data[31661] = "دشمنان در مخروطی به‌اندازهٔ 12 یارد مقابل شما، $s2 آسیب Fire دریافت می‌کنند و برای 4 ثانیه دچار سردرگمی می‌شوند. آسیب این اثر را لغو می‌کند.$?a235870[\n\nهمیشه Critical Strike می‌زند و به Hot Streak کمک می‌کند.][]"
WoWFA_Data[31687] = "یک Water Elemental احضار می‌کند تا شما را دنبال کند و برایتان بجنگد."
WoWFA_En[44614] = "Unleash a flurry of ice, striking the target $s1 times for a total of ${$228354s1*$s1} $?a1248002[Frostfire][Frost] damage.\n\n|CFFffffffApplies ${$1246769s2*$s1} $lstack:stacks; of Freezing.|R"
WoWFA_Data[44614] = "رگباری از یخ را آزاد می‌کنید و 3 بار به هدف ضربه می‌زنید؛ در مجموع ${$228354s1*$s1} آسیب $?a1248002[Frostfire][Frost] وارد می‌شود.\n\n|CFFffffff3 استک Freezing اعمال می‌کند.|R"
WoWFA_En[45438] = "Encases you in a block of ice, protecting you from all attacks and damage for $d, but during that time you cannot attack, move, or cast spells.$?a382292[\n\nWhile inside Ice Block, you heal for ${$382292s1*10}% of your maximum health over the duration.][]\n\nCauses Hypothermia, preventing you from recasting Ice Block for $41425d."
WoWFA_Data[45438] = "شما را در قطعه‌ای از یخ محصور می‌کند و برای 10 ثانیه در برابر تمام حملات و آسیب‌ها محافظت می‌کند، اما در این مدت نمی‌توانید حمله کنید، حرکت کنید یا اسپل کست کنید.$?a382292[\n\nدرون Ice Block، طی مدت اثر به‌اندازهٔ 40% از حداکثر سلامتی‌تان شفا می‌یابید.][]\n\nباعث Hypothermia می‌شود و تا 30 ثانیه از کست دوبارهٔ Ice Block جلوگیری می‌کند."
WoWFA_Data[55342] = "برای 15 ثانیه، 3 کپی از شما در نزدیکی ایجاد می‌کند که اسپل کست می‌کنند و به دشمنانتان حمله می‌کنند. هنگام فعال بودن، تهدید بسیار کمتری ایجاد می‌کنید.\n\nدریافت آسیب مستقیم باعث ناپدید شدن یکی از تصاویر شما می‌شود."
WoWFA_En[56377] = "Your Flurry and $?s431044[Frostfire Bolt][Frostbolt] spells strike $s1 additional target at $s2% effectiveness."
WoWFA_Data[56377] = "اسپل‌های Flurry و $?s431044[Frostfire Bolt][Frostbolt] شما با اثربخشی 50% به 1 هدف اضافی ضربه می‌زنند."
WoWFA_En[84714] = "Launches an orb of swirling ice in front of you, dealing up to ${20*$84721s1} Frost damage to all enemies it passes through over $d. After a short delay, Frozen Orb will pursue its target. Deals reduced damage beyond $84721s2 targets.\n\nEnemies damaged by the Frozen Orb are slowed by $205708s1% for $205708d."
WoWFA_Data[84714] = "گوی چرخانی از یخ را جلوی خود پرتاب می‌کنید که در طول 15 ثانیه، تا ${20*$84721s1} آسیب Frost به تمام دشمنانی که از میانشان عبور می‌کند وارد می‌کند. پس از مدت کوتاهی، Frozen Orb هدف خود را دنبال می‌کند. آسیب پس از 8 هدف کاهش می‌یابد.\n\nسرعت حرکت دشمنانی که Frozen Orb به آن‌ها آسیب می‌زند، به‌مدت 8 ثانیه، 50% کاهش می‌یابد."
WoWFA_Data[86949] = "آسیب مرگبار در عوض سلامتی شما را به 35% می‌رساند و سپس طی 6 ثانیه، به‌اندازهٔ 28% از حداکثر سلامتی‌تان شما را می‌سوزاند.\n\nدر هنگام سوختن، اثرات کاهندهٔ سرعت حرکت سرکوب می‌شوند و سرعت حرکت شما 150% افزایش می‌یابد.\n\nاین اثر بیش از یک‌بار در هر 6 دقیقه رخ نمی‌دهد."
WoWFA_En[108853] = "Blasts the enemy, critically striking for ${$s1*2} $?a1248002[Frostfire][Fire] damage.\n\nCastable while casting other spells."
WoWFA_Data[108853] = "به دشمن انفجار وارد می‌کند و با Critical Strike، ${$s1*2} آسیب $?a1248002[Frostfire][Fire] وارد می‌کند.\n\nهنگام کست کردن اسپل‌های دیگر نیز قابل کست است."
WoWFA_En[110959] = "Makes you invisible and untargetable for $110960d, removing all threat. Any action taken cancels this effect.$?a382293[\n\nIncreases your movement speed by ${$382293s1}% for $337278d.][]"
WoWFA_Data[110959] = "برای 20 ثانیه شما را نامرئی و غیرقابل انتخاب می‌کند و تمام تهدید را حذف می‌کند. هر اقدامی این اثر را لغو می‌کند.$?a382293[\n\nسرعت حرکت شما را برای 6 ثانیه به‌اندازهٔ 20% افزایش می‌دهد.][]"
WoWFA_En[112965] = "$?s431044[Frostfire Bolt][Frostbolt] has a $s1% chance to grant a charge of Fingers of Frost.\n\nFingers of Frost causes your next Ice Lance to deal Shatter damage equal to $1246769s4 stacks of Freezing and does not consume Freezing stacks.\n\nMaximum $44544u $Lcharge:charges;."
WoWFA_Data[112965] = "$?s431044[Frostfire Bolt][Frostbolt] شانس 15% دارد یک شارژ Fingers of Frost بدهد.\n\nFingers of Frost باعث می‌شود Ice Lance بعدی شما به‌اندازهٔ 4 استک Freezing آسیب Shatter وارد کند و استک‌های Freezing را مصرف نکند.\n\nحداکثر 2 شارژ."
WoWFA_Data[113724] = "یک Ring of Frost را برای 10 ثانیه در مکان هدف احضار می‌کند. دشمنانی که وارد حلقه شوند برای 10 ثانیه ناتوان می‌شوند. حداکثر 10 هدف.\n\nوقتی ناتوانی منقضی شود، سرعت حرکت دشمنان برای 4 ثانیه به‌اندازهٔ 65% کاهش می‌یابد."
WoWFA_Data[117216] = "اسپل‌های شما 4% شانس بیشتری برای زدن Critical Strike دارند.\n\nاز همهٔ منابع، 10% بیشتر Critical Strike دریافت می‌کنید."
WoWFA_En[153561] = "Calls down a meteor which lands at the target location after $177345d, dealing $351140s1 Fire damage to all enemies, and burns the ground, dealing ${8*$155158s1} Fire damage over $175396d to all enemies in the area.\n\n$?a1254857[The enemy closest to the center of the Meteor's impact takes $1254857s1% increased damage. ][]Damage reduced beyond 8 targets."
WoWFA_Data[153561] = "شهاب‌سنگی فرومی‌فرستد که پس از 3 ثانیه در مکان هدف فرود می‌آید، به همهٔ دشمنان $351140s1 آسیب Fire وارد می‌کند و زمین را می‌سوزاند و طی 4 ثانیه به همهٔ دشمنان در ناحیه ${8*$155158s1} آسیب Fire وارد می‌کند.\n\n$?a1254857[دشمنی که به مرکز برخورد Meteor نزدیک‌تر است، 75% آسیب بیشتری دریافت می‌کند. ][]آسیب پس از 8 هدف کاهش می‌یابد."
WoWFA_En[153626] = "Launches an Arcane Orb forward from your position, traveling up to 40 yds, dealing $153640s1 Arcane damage to enemies it passes through.\n\n|cFFFFFFFFGrants 1 Arcane Charge when cast and every time it deals damage.|r"
WoWFA_Data[153626] = "یک Arcane Orb را از موقعیت خود به جلو پرتاب می‌کنید که تا 40 یارد حرکت می‌کند و به دشمنانی که از میانشان عبور کند $153640s1 آسیب Arcane وارد می‌کند.\n\n|cFFFFFFFFهنگام کست و هر بار که آسیب وارد می‌کند، 1 Arcane Charge می‌دهد.|r"
WoWFA_En[157980] = "Pulses arcane energy around the target enemy or ally, dealing $s2 Arcane damage to all enemies within $A2 yds, and knocking them upward. A primary enemy target will take $s1% increased damage."
WoWFA_Data[157980] = "انرژی Arcane را اطراف هدف دشمن یا متحد به‌صورت موجی آزاد می‌کند و به تمام دشمنان در فاصلهٔ 8 یارد، $s2 آسیب Arcane وارد کرده و آن‌ها را به هوا پرتاب می‌کند. هدف اصلی دشمن 100% آسیب بیشتری دریافت می‌کند."
WoWFA_En[157997] = "Causes a whirl of icy wind around the enemy, dealing $s1 Frost damage to the target and all other enemies within $a2 yds, freezing them in place for $d. Damage reduced beyond $s3 targets."
WoWFA_Data[157997] = "گردبادی از باد یخی اطراف دشمن ایجاد می‌کند و به هدف و تمام دشمنان دیگر در فاصلهٔ 8 یارد، $s1 آسیب Frost وارد می‌کند و آن‌ها را برای 2 ثانیه در جای خود منجمد می‌کند. آسیب پس از 8 هدف کاهش می‌یابد."
WoWFA_En[190319] = "Engulfs you in flames for $d, increasing your spells' critical strike chance by $s1%.$?a383967[\n\nAdditionally, increases your Mastery by $383967s1% of your critical strike chance.]?a1254512[\n\nAdditionally, increases your spell damage by $s3% plus an additional $1254512s1% of your critical strike chance.]?449382[\n\nAdditionally, increases your spell damage by $s3%.][]\n\nCastable while casting other spells."
WoWFA_Data[190319] = "برای 10 ثانیه شما را در شعله‌ها فرامی‌گیرد و شانس Critical Strike اسپل‌هایتان را 100% افزایش می‌دهد.$?a383967[\n\nهمچنین Mastery شما را به‌اندازهٔ 75% از شانس Critical Strike شما افزایش می‌دهد.]?a1254512[\n\nهمچنین آسیب اسپل شما را $s3% به‌علاوهٔ 20% از شانس Critical Strike شما افزایش می‌دهد.]?449382[\n\nهمچنین آسیب اسپل شما را $s3% افزایش می‌دهد.][]\n\nهنگام کست کردن اسپل‌های دیگر نیز قابل کست است."
WoWFA_En[190356] = "Ice shards pelt the target area, dealing ${$190357m1*8} Frost damage over $d and reducing movement speed by $12486s1% for $12486d.\n\n|cFFFFFFFFThis spell is cast at a selected location"
WoWFA_Data[190356] = "تکه‌های یخ ناحیهٔ هدف را بمباران می‌کنند و در طول 12 ثانیه، ${$190357m1*8} آسیب Frost وارد می‌کنند و سرعت حرکت را 50% برای 3 ثانیه کاهش می‌دهند.\n\n|cFFFFFFFFاین اسپل در یک مکان انتخاب‌شده کست می‌شود"
WoWFA_En[190447] = "$?s431044[Frostfire Bolt][Frostbolt] has a $m1% chance to reset the remaining cooldown on Flurry and cause your next Flurry to deal $190446s2% increased damage."
WoWFA_Data[190447] = "$?s431044[Frostfire Bolt][Frostbolt] شانس 25% دارد کول‌داون باقی‌ماندهٔ Flurry را بازنشانی کند و باعث شود Flurry بعدی شما 50% آسیب بیشتری وارد کند."
WoWFA_En[205021] = "Channel an icy beam at the enemy for $d, dealing $s1 Frost damage every ${$t1}.2 sec.\n\n|CFFffffffApplies ${$d/$t1} $lstack:stacks; of Freezing over its duration.|R"
WoWFA_Data[205021] = "پرتوی یخی را به‌مدت 4 ثانیه به سمت دشمن هدایت می‌کنید و هر 0.5 ثانیه $s1 آسیب Frost وارد می‌کنید.\n\n|CFFffffffدر طول مدت خود 8 استک Freezing اعمال می‌کند.|R"
WoWFA_Data[205022] = "کست کردن Arcane Intellect، یک Familiar احضار می‌کند که به دشمنان شما حمله می‌کند و حداکثر Mana شما را به‌اندازه 10% برای 1 ساعت افزایش می‌دهد."
WoWFA_Data[205024] = "آسیب اسپل‌ها به‌اندازهٔ 3% افزایش می‌یابد."
WoWFA_En[205025] = "Causes your next $n Arcane $LBlast:Blasts; to be instant cast$?a134735[ and deal $s2% of normal damage][]."
WoWFA_Data[205025] = "باعث می‌شود 2 Arcane Blast بعدی شما کست فوری شود$?a134735[ و 100% آسیب عادی را وارد کند][]."
WoWFA_Data[205026] = "اسپل‌های Fireball و Pyroblast شما وقتی سلامتی هدف بالاتر از 90% باشد، همیشه Critical Strike می‌زنند."
WoWFA_Data[205028] = "Arcane Barrage به‌ازای هر هدفی که پس از هدف اول به آن ضربه می‌زند، 8% آسیب بیشتر وارد می‌کند."
WoWFA_Data[205029] = "Fire Blast 1 شارژ اضافی به‌دست می‌آورد و کول‌داون آن 2 ثانیه کاهش می‌یابد."
WoWFA_Data[205030] = "Frostbolt، Fingers of Frost را 25% بیشتر و Brain Freeze را 20% بیشتر به شما می‌دهد."
WoWFA_Data[205036] = "Frost Nova یک شارژ اضافی به‌دست می‌آورد."
WoWFA_En[210476] = "$?s110959[Greater ][]Invisibility's cooldown is reduced by ${-$s1/1000} sec."
WoWFA_Data[210476] = "کول‌داون $?s110959[Greater ][]Invisibility به‌اندازهٔ 60 ثانیه کاهش می‌یابد."
WoWFA_En[212653] = "Teleports you $A1 yds forward, unless something is in the way. Unaffected by the global cooldown and castable while casting.$?a382289[\n\nGain a shield that absorbs $382289s1% of your maximum health for $382290d after you Shimmer.][]"
WoWFA_Data[212653] = "شما را 20 یارد به جلو تله‌پورت می‌کند، مگر این‌که مانعی در مسیر باشد. از Global Cooldown تأثیر نمی‌پذیرد و هنگام کست کردن نیز قابل کست است.$?a382289[\n\nپس از Shimmer، برای 15 ثانیه سپری به‌دست می‌آورید که 3% از حداکثر سلامتی‌تان را جذب می‌کند.][]"
WoWFA_Data[231564] = "به‌ازای هر Arcane Charge، Arcane Barrage به 1 هدف نزدیک اضافی با 40% آسیب ضربه می‌زند."
WoWFA_En[235219] = "Resets the cooldown of your Ice Barrier, Frost Nova, $?a417493[][Cone of Cold, ]Ice Cold, and Ice Block."
WoWFA_Data[235219] = "کول‌داون Ice Barrier، Frost Nova، $?a417493[][Cone of Cold، ]Ice Cold و Ice Block شما را بازنشانی می‌کند."
WoWFA_En[235313] = "Shields you in flame, absorbing $<shield> damage$?s194315[ and reducing Physical damage taken by $s3%][] for $d.\n\nMelee attacks against you cause the attacker to take $235314s1 Fire damage."
WoWFA_Data[235313] = "شما را در شعله‌ها محاصره می‌کند و برای 1 دقیقه، $<shield> آسیب را جذب می‌کند$?s194315[ و آسیب Physical دریافتی را $s3% کاهش می‌دهد][].\n\nحملات نزدیک علیه شما باعث می‌شوند مهاجم $235314s1 آسیب Fire دریافت کند."
WoWFA_En[235450] = "Shields you with an arcane force, absorbing $<shield> damage and reducing magic damage taken by $s3% for $d.\n\nThe duration of harmful Magic effects against you is reduced by $s4%."
WoWFA_Data[235450] = "با نیروی Arcane از شما محافظت می‌کند و برای 1 دقیقه، $<shield> آسیب را جذب می‌کند و آسیب Magic دریافتی را 15% کاهش می‌دهد.\n\nمدت اثرات مضر Magic روی شما 25% کاهش می‌یابد."
