WoWFA_Data[431166] = "$?a137020[Frostfire Bolt، Brain Freeze را 5% بیشتر می‌دهد]?a137019[شانس Critical Strike Frostfire Bolt 15% افزایش می‌یابد][Frostfire Bolt، Brain Freeze را 5% بیشتر می‌دهد و شانس Critical Strike آن 15% افزایش می‌یابد].\n\nآسیب اسپل‌های Frost و Fire شما 4% افزایش می‌یابد."
WoWFA_En[431176] = "Casting Frostfire spells has a $s3% chance to activate Frostfire Empowerment, causing your next Frostfire Bolt to be instant cast, deal $431177s3% increased damage, and explode for $s2% of its damage to nearby enemies. Damage reduced beyond $s5 targets.$?c2[][\n\nDamage from Frostfire Empowerment applies $s4 $Lstack:stacks; of Freezing.]"
WoWFA_Data[431176] = "کست کردن اسپل‌های Frostfire، 10% شانس دارد Frostfire Empowerment را فعال کند و باعث شود Frostfire Bolt بعدی شما فوری کست شود، 60% آسیب بیشتری وارد کند و به‌اندازهٔ 60% از آسیب خود به دشمنان نزدیک انفجار وارد کند. آسیب پس از 5 هدف کاهش می‌یابد.$?c2[][\n\nآسیب Frostfire Empowerment، 1 استک Freezing اعمال می‌کند.]"
WoWFA_En[431178] = "$?a137020[Glacial Spike damage increased by $s1% and it now explodes on impact, dealing $s2% of its damage to up to $s3 nearby enemies.\n\nAdditionally, Glacial Spike now grants Frostfire Empowerment][Meteor's damage is increased by $s4%.\n\nMeteor now grants Frostfire Empowerment]."
WoWFA_Data[431178] = "$?a137020[آسیب Glacial Spike 15% افزایش می‌یابد و اکنون هنگام برخورد منفجر می‌شود و به حداکثر 5 دشمن نزدیک، 25% از آسیب خود را وارد می‌کند.\n\nهمچنین Glacial Spike اکنون Frostfire Empowerment می‌دهد][آسیب Meteor 25% افزایش می‌یابد.\n\nMeteor اکنون Frostfire Empowerment می‌دهد]."
WoWFA_Data[431189] = "Frostfire Empowerment، 1 بار بیشتر استک می‌شود و باعث می‌شود Frostfire Bolt به‌اندازهٔ 20% دیگر از آسیب خود منفجر شود."
WoWFA_En[443739] = "$?c1[Casting Arcane Blast or Arcane Pulse][Casting Frostbolt or Flurry] conjures $?c1[an Arcane][a Frost] Splinter.\n$?c1[\n$@spellicon443763$@spellname443763:\n$@spelldesc443763\n]\n[\n$@spellicon443722$@spellname443722:\n$@spelldesc443722\n]"
WoWFA_Data[443739] = "$?c1[کست Arcane Blast یا Arcane Pulse][کست Frostbolt یا Flurry] یک $?c1[Arcane][Frost] Splinter احضار می‌کند.\n$?c1[\nArcane Splinter:\nConjure raw Arcane magic into a sharp projectile that deals $s1 Arcane damage.\n]\n[\nFrost Splinter:\nConjure raw Frost magic into a sharp projectile that deals $s1 Frost damage.\n]"
WoWFA_En[443783] = "$?c1[Casting Arcane Surge conjures $s1 Arcane Splinters][Each time Ray of Frost damages one or more enemies, it conjures $s3 Frost $LSplinter:Splinters;].\n\n$?c1[During Arcane Surge, your chance to conjure an additional Arcane Splinter is increased to $s2%][For $1247908d after casting Ray of Frost, your chance to conjure an additional Frost Splinter is increased to $s2%]."
WoWFA_Data[443783] = "$?c1[کست Arcane Surge، 8 Arcane Splinter احضار می‌کند][هر بار که Ray of Frost به یک یا چند دشمن آسیب می‌زند، 1 Frost ترکش احضار می‌کند].\n\n$?c1[در طول Arcane Surge، شانس شما برای احضار یک Arcane Splinter اضافی به 100% افزایش می‌یابد][پس از کست Ray of Frost و به‌مدت 10 ثانیه، شانس شما برای احضار یک Frost Splinter اضافی به 100% افزایش می‌یابد]."
WoWFA_En[444256] = "Enemies damaged by your $?c1[Arcane Orb][Frozen Orb] conjure $?c1[$s4 Arcane][$s5 Frost] $LSplinter:Splinters;, up to $?c1[$s1][$s6].\n\n$?c1[Arcane Orb][Frozen Orb] damage is increased by $s3%."
WoWFA_Data[444256] = "دشمنانی که با $?c1[Arcane Orb][Frozen Orb] شما آسیب می‌بینند، $?c1[2 Arcane][1 Frost] ترکش ایجاد می‌کنند، حداکثر $?c1[4][4].\n\nآسیب $?c1[Arcane Orb][Frozen Orb] به‌اندازه 25% افزایش می‌یابد."
WoWFA_En[444483] = "$?c1[$s1%][$s4%] of the direct damage dealt by $?c1[an Arcane Splinter][a Frost Splinter] is also dealt to nearby enemies. Damage reduced beyond $s5 targets."
WoWFA_Data[444483] = "$?c1[40%][60%] از آسیب مستقیم واردشده توسط $?c1[یک Arcane Splinter][یک Frost Splinter] به دشمنان نزدیک نیز وارد می‌شود. پس از 5 هدف، آسیب کاهش می‌یابد."
WoWFA_En[444675] = "Gaining $?c1[Clearcasting][Brain Freeze] conjures $s1 $?c1[Arcane][Frost] $lSplinter:Splinters;."
WoWFA_Data[444675] = "دریافت $?c1[Clearcasting][Brain Freeze]، 2 $?c1[Arcane][Frost] ترکش احضار می‌کند."
WoWFA_En[444719] = "$?c1[Casting Arcane Barrage conjures an Arcane Splinter for every $s1 Arcane Salvo stacks consumed][Ice Lance conjures a Frost Splinter for every $s3 Freezing stacks Shattered from its primary target]."
WoWFA_Data[444719] = "$?c1[کست Arcane Barrage برای هر 5 استک Arcane Salvo مصرف‌شده، یک Arcane Splinter احضار می‌کند][Ice Lance برای هر 2 استک Freezing که از هدف اصلی خود Shatter می‌کند، یک Frost Splinter احضار می‌کند]."
WoWFA_En[444752] = "You have $s1% increased movement speed during Alter Time$?a236457[ and Evocation][].\n"
WoWFA_Data[444752] = "در طول Alter Time$?a236457[ و Evocation][]، سرعت حرکت شما 40% بیشتر است."
WoWFA_En[444756] = "While in combat, $?s212653[Shimmer][Blink] summons a Mirror Image at your previous location."
WoWFA_Data[444756] = "در حال مبارزه، $?s212653[Shimmer][Blink] در محل قبلی شما یک Mirror Image احضار می‌کند."
WoWFA_Data[444784] = "کست Mirror Image، 1 کپی اضافی از شما احضار می‌کند."
WoWFA_En[444827] = "Your $?c1[Prismatic][Ice] Barrier can absorb up to $s1% more damage based on your missing health.\n\nMax effectiveness when under $s1% health."
WoWFA_Data[444827] = "بر اساس سلامتی ازدست‌رفته‌تان، $?c1[Prismatic][Ice] Barrier شما می‌تواند تا 25% آسیب بیشتری جذب کند.\n\nحداکثر اثربخشی در کمتر از 25% سلامتی."
WoWFA_En[444968] = "$?c1[Arcane Surge][Ray of Frost] damage increased by $?c1[$s1][$s2]%.\n\nYour chance to gain $?c1[Clearcasting][Brain Freeze from Frostbolt] is increased by $?c1[$s3][$s4]%."
WoWFA_Data[444968] = "$?c1[آسیب Arcane Surge][آسیب Ray of Frost] به‌اندازه $?c1[30][20]% افزایش می‌یابد.\n\nشانس شما برای دریافت $?c1[Clearcasting][Brain Freeze از Frostbolt] به‌اندازه $?c1[3][5]% افزایش می‌یابد."
WoWFA_En[444986] = "Direct damage from $?c1[Arcane][Frost] Splinters reduces the cooldown of $?c1[Arcane][Frozen] Orb by $?c1[${$s1/1000}.2][${$s2/1000}.2] sec."
WoWFA_Data[444986] = "آسیب مستقیم $?c1[Arcane][Frost] Splinterها، کول‌داون $?c1[Arcane][Frozen] Orb را به‌اندازه $?c1[0.3][0.3] ثانیه کاهش می‌دهد."
WoWFA_En[448601] = "$?c1[Casting a damaging spell][Consuming Hot Streak] has a $?c1[$s1][$s2]% chance to conjure a Spellfire Sphere.\n\nWhile you're out of combat, you will slowly conjure Spellfire Spheres over time.\n\n$@spellicon448604 $@spellname448604\n$@spelldesc448604"
WoWFA_Data[448601] = "$?c1[کست یک اسپل آسیب‌زننده][مصرف Hot Streak]، $?c1[6][12]% شانس دارد یک Spellfire Sphere احضار کند.\n\nوقتی خارج از مبارزه هستید، به‌مرور زمان Spellfire Spheres احضار می‌کنید.\n\n Spellfire Sphere\nIncreases your spell damage by $?c1[1][1]%. Stacks up to 3 times."
WoWFA_En[448658] = "When you cast $?c1[Arcane Surge][Combustion], summon an Arcane Phoenix to aid you in battle.\n\n$@spellicon448659  $@spellname448659\nYour Arcane Phoenix aids you for the duration of your $?c1[Arcane Surge][Combustion], casting random Arcane and Fire spells."
WoWFA_Data[448658] = "وقتی $?c1[Arcane Surge][Combustion] را کست می‌کنید، یک Arcane Phoenix برای کمک در نبرد احضار می‌کنید.\n\n  Arcane Phoenix\nArcane Phoenix شما در طول مدت $?c1[Arcane Surge][Combustion] به شما کمک می‌کند و اسپل‌های تصادفی Arcane و Fire کست می‌کند."
WoWFA_En[449293] = "$?c1[Casting Arcane Blast, Arcane Pulse, Arcane Barrage, or Prismatic Bolt][Consuming Hot Streak] grants you $?c1[${$449322s2/10}.1][${$449314s2/10}.1]% Haste for $449322d. Multiple applications may overlap."
WoWFA_Data[449293] = "$?c1[کست Arcane Blast، Arcane Pulse، Arcane Barrage یا Prismatic Bolt][مصرف Hot Streak] به شما $?c1[0.5][0.5]% Haste برای 6 ثانیه می‌دهد. اعمال متعدد ممکن است روی هم قرار بگیرند."
WoWFA_En[449330] = "The bonuses provided by your Barrier spells persist at $s3% effectiveness for an additional $?c1[$449336d][$1246023d] after your Barrier is removed.$?c1[][\n\nAdditionally, Cauterize no longer deals damage to you.]"
WoWFA_Data[449330] = "مزایای ارائه‌شده توسط اسپل‌های Barrier شما پس از حذف Barrier، با اثربخشی 100% برای مدت اضافی $?c1[8 ثانیه][8 ثانیه] باقی می‌مانند.$?c1[][\n\nعلاوه بر این، Cauterize دیگر به شما آسیب نمی‌زند.]"
WoWFA_En[449349] = "$?c2[Pyroclasm's damage bonus is increased by $s1% and Meteor grants Pyroclasm if talented.][Arcane Barrage deals $s2% increased damage to enemies affected by your Touch of the Magi.]"
WoWFA_Data[449349] = "$?c2[پاداش آسیب Pyroclasm به‌اندازه 20% افزایش می‌یابد و Meteor در صورت داشتن talent، Pyroclasm را فعال می‌کند.][Arcane Barrage به دشمنان متأثر از Touch of the Magi، 5% آسیب بیشتری وارد می‌کند.]"
WoWFA_En[449382] = "When your Arcane Phoenix is summoned, it consumes all your Spellfire Spheres.\n\nEach Sphere consumed increases your spell damage during $?c1[Arcane Surge][Combustion] by $?c1[$s1][$s2]% and causes your Arcane Phoenix to cast an exceptional Arcane or Fire spell over its duration."
WoWFA_Data[449382] = "وقتی Arcane Phoenix شما احضار می‌شود، تمام Spellfire Spheres شما را مصرف می‌کند.\n\nهر Sphere مصرف‌شده، آسیب اسپل شما را در طول $?c1[Arcane Surge][Combustion] به‌اندازه $?c1[1][1]% افزایش می‌دهد و باعث می‌شود Arcane Phoenix شما در طول مدت خود یک Exceptional Arcane یا Fire spell کست کند."
WoWFA_En[449394] = "$?c2[Generating a Spellfire Sphere causes your next cast of Fire Blast to call down a storm of $s1 Meteorites on its target.][Arcane Barrage summons $s6 $LMeteorite:Meteorites; for every $s4 Arcane Salvo stacks consumed.]\n\n$@spellicon449559 $@spellname449559\n$@spelldesc449559"
WoWFA_Data[449394] = "$?c2[ایجاد یک Spellfire Sphere باعث می‌شود کست بعدی Fire Blast شما طوفانی شامل 4 Meteorite بر هدفش فرود آورد.][Arcane Barrage به‌ازای هر 5 استک Arcane Salvo مصرف‌شده، 1 شهاب‌سنگ احضار می‌کند.]\n\n Meteorite\nCalls down a meteorite which lands at the target location after 3 ثانیه, dealing $449569s1 Fire damage to all enemies hit, reduced beyond 8 targets."
WoWFA_En[449412] = "When you cast $?c1[Arcane Surge][Combustion], its duration is extended by ${$s1/1000}.1 sec for each Spellfire Sphere you have, up to ${$s2/1000}.1 sec."
WoWFA_Data[449412] = "وقتی $?c1[Arcane Surge][Combustion] را کست می‌کنید، مدت آن به‌ازای هر Spellfire Sphere که دارید، 0.8 ثانیه افزایش می‌یابد؛ حداکثر تا 2.4 ثانیه."
WoWFA_En[449596] = "Your chance to generate a Spellfire Sphere is increased by $?c1[$s1][$s2]%.\n\nSpellfire Spheres grant an additional $s3% spell damage."
WoWFA_Data[449596] = "شانس شما برای ایجاد یک Spellfire Sphere به‌اندازه $?c1[6][12]% افزایش می‌یابد.\n\nSpellfire Spheres، 1% آسیب اسپل اضافی می‌دهند."
WoWFA_En[449619] = "When your Arcane Phoenix expires it empowers you, granting $?c1[Arcane Soul][Hyperthermia] for $?c1[${$s1/1000}.1][${$s2/1000}.1] sec.\n\n$?c1[$@spellicon451038$@spellname451038:\n$@spelldesc451038][$@spellicon383874 $@spellname383874:\n$@spellaura383874]"
WoWFA_Data[449619] = "وقتی Arcane Phoenix شما منقضی می‌شود، شما را تقویت می‌کند و $?c1[Arcane Soul][Hyperthermia] را برای $?c1[4][4] ثانیه به شما می‌دهد.\n\n$?c1[Arcane Soul:\nArcane Barrage grants Clearcasting and generates 4 Arcane Charges.\n\nEach cast of Arcane Barrage grants 5 stacks of Arcane Salvo and casting Arcane Barrage does not consume Arcane Salvo.][ Hyperthermia:\nPyroblast and Flamestrike have no cast time, are guaranteed to critically strike, and increase the damage of Pyroblast and Flamestrike by 15%.]"
WoWFA_Data[449627] = "Arcane Phoenix شما چند ترفند یاد گرفته است و هنگام احضار شدن و منقضی شدن، Spellsteal می‌کند."
WoWFA_Data[450746] = "Fireball همیشه به دشمنانی که سلامتی‌شان کمتر از 30% است Critical Strike می‌زند.\n\nوقتی Fireball یا Scorch به دشمنی با سلامتی کمتر از 30% آسیب می‌زنند، Fireball 25% و Scorch 250% آسیب بیشتری وارد می‌کنند."
WoWFA_Data[450831] = "شانس Critical Strike اسپل‌های شما 2.5% افزایش می‌یابد.\n\nCombustion آسیب Critical Strike شما را 2.5% افزایش می‌دهد."
WoWFA_En[451035] = "$?c1[Arcane Blast damage increased by $s3%.\n\nArcane Pulse damage increased by $s4%][Pyroblast damage increased by $s1%.\n\nFlamestrike damage increased by $s2%]."
WoWFA_Data[451035] = "$?c1[آسیب Arcane Blast به‌اندازه 30% افزایش می‌یابد.\n\nآسیب Arcane Pulse به‌اندازه 20% افزایش می‌یابد][آسیب Pyroblast به‌اندازه 3% افزایش می‌یابد.\n\nآسیب Flamestrike به‌اندازه 6% افزایش می‌یابد]."
WoWFA_Data[451466] = "کست کردن Pyroblast یا Flamestrike در حالی که Hot Streak فعال است، 6% شانس دارد کست اسپل را با اثربخشی 50% تکرار کند.\n\nاین اثر به‌عنوان مصرف کردن Hot Streak محسوب می‌شود."
WoWFA_Data[451875] = "کست کردن Combustion حداکثر 1 شارژ Fire Blast را تازه می‌کند."
WoWFA_Data[452198] = "وقتی یک جادو Clearcasting را مصرف می‌کند، آسیب آن 20% افزایش می‌یابد."
WoWFA_Data[452997] = "در طول Arcane Surge، Arcane Familiar شما به‌جای 1، 4 پرتابه شلیک می‌کند.\n\nآسیب Arcane Familiar شما 6% شانس دارد 2% از حداکثر Mana شما را بازگرداند."
WoWFA_Data[453282] = "زمان کست Pyroblast و Flamestrike 20% کاهش می‌یابد."
WoWFA_En[455428] = "When $?c1[Prismatic]?c2[Blazing][Ice] Barrier is removed, its remaining cooldown is reduced by ${$s1/1000} sec."
WoWFA_Data[455428] = "وقتی Barrierِ $?c1[Prismatic]?c2[Blazing][Ice] حذف شود، کول‌داون باقی‌ماندهٔ آن 5 ثانیه کاهش می‌یابد."
WoWFA_Data[457521] = "آسیب Arcane Surge بر اساس Mana مصرف‌شده، 50% دیگر افزایش می‌یابد."
WoWFA_Data[457735] = "وقتی Combustion فعال نیست، آسیب Ignite شانس کمی دارد Scorch بعدی شما را فوری کند، 100% آسیب بیشتری وارد کند و چنان آسیب بزند که گویی سلامتی هدف شما کمتر از 30% است."
WoWFA_Data[457803] = "آسیب واردشده به اهدافی که سلامتی‌شان کمتر از 35% است، 15% افزایش می‌یابد."
WoWFA_Data[458437] = "Arcane Intellect، 2% Intellect اضافی به شما می‌دهد."
WoWFA_Data[460590] = "Frozen Orb در طول مدت خود، آسیب Shatter را 10% افزایش می‌دهد."
WoWFA_Data[461248] = "هر موج Arcane Missiles، 50% شانس دارد 1 Arcane Charge به شما بدهد.\n\nآسیب Arcane Missiles به‌اندازه 20% افزایش می‌یابد."
WoWFA_Data[461251] = "هر موج Arcane Missiles یک Arcane Charge مصرف می‌کند تا آسیب آن را 40% افزایش دهد."
WoWFA_Data[461257] = "هر موج Arcane Missiles، 50% شانس دارد 1 استک اضافی Arcane Salvo بدهد."
WoWFA_Data[461260] = "هزینه Mana مربوط به Arcane Blast را 5% کاهش می‌دهد و آسیب آن را 8% افزایش می‌دهد."
WoWFA_En[461261] = "Gaining $?a137021[Clearcasting]?a137020[Brain Freeze][Hot Streak] increases your Intellect by $461531s1% for $461531d. Multiple instances may overlap."
WoWFA_Data[461261] = "به‌دست‌آوردن $?a137021[Clearcasting]?a137020[Brain Freeze][Hot Streak]، Intellect شما را به‌مدت 8 ثانیه به‌اندازهٔ 1% افزایش می‌دهد. چند نمونه از این اثر می‌توانند روی هم قرار بگیرند."
WoWFA_En[470021] = "$?c1[Arcane Blast and Arcane Pulse damage increased by $s3%.\n\nCasting Touch of the Magi conjures $s1 Arcane Splinters][Frostbolt and Blizzard damage increased by $s4%.\n\nGlacial Spike conjures $s2 additional Frost Splinters]."
WoWFA_Data[470021] = "$?c1[آسیب Arcane Blast و Arcane Pulse به‌اندازه 15% افزایش می‌یابد.\n\nکست Touch of the Magi، 4 Arcane Splinter احضار می‌کند][آسیب Frostbolt و Blizzard به‌اندازه 25% افزایش می‌یابد.\n\nGlacial Spike، 2 Frost Splinter اضافی احضار می‌کند]."
WoWFA_Data[1216953] = "Shatter کردن دشمنان درون Blizzard شما، آسیب ناحیه‌ای Shatter را 15% افزایش می‌دهد."
WoWFA_Data[1223798] = "پس از رسیدن Arcane Salvo به حداکثر استک، Arcane Barrage بعدی شما 25% آسیب بیشتر وارد می‌کند."
WoWFA_En[1241462] = "A pulse of Arcane magic erupts from underneath your target, dealing $s1 Arcane damage to all enemies within $A1 yds. Damage reduced beyond $s2 targets.\n\n|cFFFFFFFFGenerates $1295977s1 Arcane $LCharge:Charges; for each enemy struck.|r"
WoWFA_Data[1241462] = "تپشی از جادوی Arcane از زیر هدف شما فوران می‌کند و به همه دشمنان در فاصله 8 یارد، $s1 آسیب Arcane وارد می‌کند. پس از 5 هدف، آسیب کاهش می‌یابد.\n\n|cFFFFFFFFبه‌ازای هر دشمنِ ضربه‌خورده، 1 Arcane Charge تولید می‌کند.|r"
WoWFA_Data[1243307] = "Arcane Missiles اکنون به 2 هدف اضافی با اثربخشی 50% آسیب وارد می‌کند."
WoWFA_Data[1243435] = "کست کردن Arcane Orb، 2 Arcane Orb اضافی با اثربخشی 50% شلیک می‌کند."
WoWFA_Data[1243507] = "کست کردن Touch of the Magi، Clearcasting به شما می‌دهد."
