WoWFA_Data[1244090] = "وقتی سلامتی شما به کمتر از 25% برسد، خود گذشته‌تان در صورتی که Alter Time در کول‌داون نباشد خط زمانی‌تان را اصلاح می‌کند؛ فوراً 20% از حداکثر سلامتی‌تان را بازمی‌گرداند و طی 6 ثانیه، به‌اندازهٔ 30% دیگر شما را شفا می‌دهد.\n\nاین اثر Alter Time را طوری در کول‌داون قرار می‌دهد که انگار کست شده است."
WoWFA_Data[1244105] = "آسیب Critical Strike اسپل‌های شما 5% افزایش می‌یابد."
WoWFA_Data[1244107] = "Mastery به‌اندازهٔ 3% افزایش می‌یابد."
